<?php
$pagetitle='Miniature Editor'; include_once('header.php');
if(!isset($_SESSION['userid'])||(int)($_SESSION['admin']??0)!==1){http_response_code(403);echo '<center>Access denied.</center>';include_once('footer.php');exit;}
$rarities=['White','Purple','Gold','Green'];$message='';$error='';
function mini_wiki_ok(string $u):bool{if($u==='')return true;if(!filter_var($u,FILTER_VALIDATE_URL))return false;$p=parse_url($u);return isset($p['scheme'],$p['host'])&&$p['scheme']==='https'&&strtolower($p['host'])==='wiki.guildwars.com';}
if($_SERVER['REQUEST_METHOD']==='POST'){
 $action=(string)($_POST['action']??'');$name=trim((string)($_POST['mininame']??''));$rarity=(string)($_POST['rarity']??'White');$wiki=trim((string)($_POST['wiki_url']??''));$groups=array_values(array_unique(array_filter(array_map('intval',(array)($_POST['groups']??[])),fn($v)=>$v>0)));
 if(in_array($action,['create','update'],true)){if($name===''||mb_strlen($name)>100)$error='Miniature name is required and must be 100 characters or fewer.';elseif(!in_array($rarity,$rarities,true))$error='Select a valid rarity.';elseif(!mini_wiki_ok($wiki))$error='Wiki URL must be an https://wiki.guildwars.com/ address.';elseif(!$groups)$error='Select at least one tracker section.';}
 if($error===''&&$action==='create'){$con->begin_transaction();try{$s=$con->prepare("INSERT INTO gwminiatures (mininame,rarity,wiki_url) VALUES (?,?,NULLIF(?,''))");$s->bind_param('sss',$name,$rarity,$wiki);$s->execute();$id=(int)$con->insert_id;$s->close();$m=$con->prepare('INSERT INTO gwminiature_group_members (groupid,miniid,display_order) VALUES (?,?,0)');foreach($groups as $g){$m->bind_param('ii',$g,$id);$m->execute();}$m->close();$con->commit();$message='Miniature created.';$_GET['miniid']=$id;}catch(Throwable $e){$con->rollback();$error=($e instanceof mysqli_sql_exception&&$e->getCode()===1062)?'A miniature with that name already exists.':'Unable to create miniature.';}}
 elseif($error===''&&$action==='update'){$id=(int)($_POST['miniid']??0);$q=$con->prepare('SELECT miniid FROM gwminiatures WHERE miniid=?');$q->bind_param('i',$id);$q->execute();$found=$q->get_result()->fetch_assoc();$q->close();if(!$found)$error='Miniature not found.';else{$con->begin_transaction();try{$s=$con->prepare("UPDATE gwminiatures SET mininame=?,rarity=?,wiki_url=NULLIF(?,'') WHERE miniid=?");$s->bind_param('sssi',$name,$rarity,$wiki,$id);$s->execute();$s->close();$d=$con->prepare('DELETE FROM gwminiature_group_members WHERE miniid=?');$d->bind_param('i',$id);$d->execute();$d->close();$m=$con->prepare('INSERT INTO gwminiature_group_members (groupid,miniid,display_order) VALUES (?,?,0)');foreach($groups as $g){$m->bind_param('ii',$g,$id);$m->execute();}$m->close();$con->commit();$message='Miniature updated.';$_GET['miniid']=$id;}catch(Throwable $e){$con->rollback();$error=($e instanceof mysqli_sql_exception&&$e->getCode()===1062)?'A miniature with that name already exists.':'Unable to update miniature.';}}}
 elseif($action==='delete'){$id=(int)($_POST['miniid']??0);$confirm=(string)($_POST['confirm_name']??'');$s=$con->prepare('SELECT mininame FROM gwminiatures WHERE miniid=?');$s->bind_param('i',$id);$s->execute();$row=$s->get_result()->fetch_assoc();$s->close();if(!$row)$error='Miniature not found.';elseif(!hash_equals($row['mininame'],$confirm))$error='Deletion confirmation did not match the miniature name.';else{$d=$con->prepare('DELETE FROM gwminiatures WHERE miniid=?');$d->bind_param('i',$id);$d->execute();$d->close();$message='Miniature deleted, including associated tracker inventory.';unset($_GET['miniid']);}}
}
$groups=[];$r=$con->query("SELECT groupid,groupname FROM gwminiature_groups WHERE groupkey<>'year6' ORDER BY display_order,groupname");while($x=$r->fetch_assoc())$groups[]=$x;$minis=[];$r=$con->query('SELECT miniid,mininame FROM gwminiatures ORDER BY mininame');while($x=$r->fetch_assoc())$minis[]=$x;$selected=null;$sg=[];$sid=(int)($_GET['miniid']??0);if($sid){$s=$con->prepare('SELECT miniid,mininame,rarity,wiki_url FROM gwminiatures WHERE miniid=?');$s->bind_param('i',$sid);$s->execute();$selected=$s->get_result()->fetch_assoc();$s->close();if($selected){$s=$con->prepare('SELECT groupid FROM gwminiature_group_members WHERE miniid=?');$s->bind_param('i',$sid);$s->execute();$rr=$s->get_result();while($x=$rr->fetch_assoc())$sg[]=(int)$x['groupid'];$s->close();}}
?>
<style>.ma{max-width:1000px;margin:auto;padding:10px 18px 40px}.ma h1,.ma-lead{text-align:center}.ma-lead,.ma-help{color:#a9c5d1}.ma-grid{display:grid;grid-template-columns:1fr 1fr;gap:18px}.ma-card{border:1px solid #2d6978;border-radius:8px;background:#122936;padding:22px}.ma-card h2{color:#69dbe1}.ma-field{margin:0 0 15px}.ma-field>label{display:block;font-weight:700;margin-bottom:6px}.ma-field input[type=text],.ma-field input[type=url],.ma-field select{width:100%;box-sizing:border-box;padding:10px}.ma-groups{display:grid;grid-template-columns:1fr 1fr;gap:8px}.ma-btn{display:inline-block;padding:10px 14px;border:1px solid #2999a5;border-radius:5px;background:#174454;color:#fff;font-weight:700;text-decoration:none;cursor:pointer}.ma-danger{background:#4a2525;border-color:#a85a5a}.ma-msg{max-width:760px;margin:0 auto 18px;padding:11px;text-align:center;border-radius:6px}.ma-ok{background:#194d31}.ma-err{background:#3b2020}.ma-delete{border-top:1px solid #36525e;margin-top:22px;padding-top:18px}.ma-actions{margin-top:18px;display:flex;gap:10px}@media(max-width:760px){.ma-grid{grid-template-columns:1fr}.ma-groups{grid-template-columns:1fr}}</style>
<section class="ma"><h1>Miniature editor</h1><p class="ma-lead">Create and maintain the tracker catalog. A miniature may belong to more than one section.</p><?php if($message)echo '<div class="ma-msg ma-ok">'.h($message).'</div>';if($error)echo '<div class="ma-msg ma-err">'.h($error).'</div>';?><div class="ma-grid"><div class="ma-card"><h2>Create miniature</h2><form method="post"><?=csrf_input()?><input type="hidden" name="action" value="create"><div class="ma-field"><label>Name</label><input type="text" name="mininame" maxlength="100" required></div><div class="ma-field"><label>Rarity</label><select name="rarity"><?php foreach($rarities as $v)echo '<option>'.h($v).'</option>';?></select></div><div class="ma-field"><label>Guild Wars Wiki URL</label><input type="url" name="wiki_url" placeholder="https://wiki.guildwars.com/wiki/Miniature_..."><small class="ma-help">Optional; the miniature name becomes the link.</small></div><div class="ma-field"><label>Tracker sections</label><div class="ma-groups"><?php foreach($groups as $g)echo '<label><input type="checkbox" name="groups[]" value="'.(int)$g['groupid'].'"> '.h($g['groupname']).'</label>';?></div></div><button class="ma-btn">Create miniature</button></form></div><div class="ma-card"><h2>Edit miniature</h2><form method="get"><div class="ma-field"><label>Select miniature</label><select name="miniid" required><option value="">Choose miniature…</option><?php foreach($minis as $m)echo '<option value="'.(int)$m['miniid'].'"'.($sid===(int)$m['miniid']?' selected':'').'>'.h($m['mininame']).'</option>';?></select></div><button class="ma-btn">Edit miniature</button></form><?php if($selected):?><form method="post" style="margin-top:22px"><?=csrf_input()?><input type="hidden" name="action" value="update"><input type="hidden" name="miniid" value="<?=(int)$selected['miniid']?>"><div class="ma-field"><label>Name</label><input type="text" name="mininame" maxlength="100" required value="<?=h($selected['mininame'])?>"></div><div class="ma-field"><label>Rarity</label><select name="rarity"><?php foreach($rarities as $v)echo '<option'.($selected['rarity']===$v?' selected':'').'>'.h($v).'</option>';?></select></div><div class="ma-field"><label>Guild Wars Wiki URL</label><input type="url" name="wiki_url" value="<?=h((string)$selected['wiki_url'])?>"></div><div class="ma-field"><label>Tracker sections</label><div class="ma-groups"><?php foreach($groups as $g)echo '<label><input type="checkbox" name="groups[]" value="'.(int)$g['groupid'].'"'.(in_array((int)$g['groupid'],$sg,true)?' checked':'').'> '.h($g['groupname']).'</label>';?></div></div><button class="ma-btn">Save changes</button></form><div class="ma-delete"><strong>Delete miniature</strong><p class="ma-help">Deletes this catalog item and every user's dedication/on-hand record. Type the exact name to confirm.</p><form method="post"><?=csrf_input()?><input type="hidden" name="action" value="delete"><input type="hidden" name="miniid" value="<?=(int)$selected['miniid']?>"><div class="ma-field"><input type="text" name="confirm_name" required placeholder="<?=h($selected['mininame'])?>"></div><button class="ma-btn ma-danger">Permanently delete miniature</button></form></div><?php endif;?></div></div><div class="ma-actions"><a class="ma-btn" href="adminlanding.php">Back to Administration</a><a class="ma-btn" href="miniatures.php">Open Miniature Tracker</a></div></section><?php include_once('footer.php');?>
